using System.Net;using System.Text.Json;using System.Text.RegularExpressions;
namespace GameTranslator.Translation;
/// <summary>Exact, game-scoped, reviewed corrections. Incoming reports never auto-train a model.</summary>
public static class CommunityCorrections {
 private const string Url="https://raw.githubusercontent.com/Tariq-220/ArabicGamesTranslator/main/community/reviewed-dialogue.json";
 private static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ArabicGames","Quality");
 private static readonly object Sync=new();private static Dictionary<string,string>? community,personal;private static bool refreshing;private static int revision;
 public static bool Automatic {get=>!File.Exists(Path.Combine(Root,"disable-community-updates"));set{Directory.CreateDirectory(Root);if(value)File.Delete(Path.Combine(Root,"disable-community-updates"));else File.WriteAllText(Path.Combine(Root,"disable-community-updates"),"");}}
 private static string GameKey(string game){var name=Regex.Replace(game.Trim().ToLowerInvariant(),@"\s+"," ");return DialogueProfile.Rdr2(game)?"rdr2":name is "gta6" or "gta 6" or "gta vi" or "grand theft auto 6" or "grand theft auto6"?"grand theft auto vi":name;}
 private static string Key(string game,string text)=>GameKey(game)+"\n"+Regex.Replace(text.Replace('\u2019','\''),@"\s+"," ").Trim().ToLowerInvariant();
 public static Dictionary<string,string> Parse(string json){using var doc=JsonDocument.Parse(json);var root=doc.RootElement;if(root.GetProperty("format").GetString()!="arabic-games-reviewed-v1"||root.GetProperty("source").GetString()!="en"||root.GetProperty("target").GetString()!="ar")throw new InvalidDataException("Invalid correction pack.");var entries=root.GetProperty("entries");if(entries.GetArrayLength()>10000)throw new InvalidDataException("Too many corrections.");var output=new Dictionary<string,string>();foreach(var e in entries.EnumerateArray()){string game=e.GetProperty("game").GetString()!,source=e.GetProperty("source").GetString()!,arabic=e.GetProperty("arabic").GetString()!;if(!e.GetProperty("reviewed").GetBoolean()||string.IsNullOrWhiteSpace(game)||game.Length>200||string.IsNullOrWhiteSpace(source)||source.Length>2000||string.IsNullOrWhiteSpace(arabic)||arabic.Length>3000)throw new InvalidDataException("Unreviewed or invalid correction.");var key=Key(game,source);if(output.TryGetValue(key,out var previous)&&previous!=arabic)throw new InvalidDataException("Conflicting correction.");output[key]=arabic;}return output;}
 public static int RevisionOf(string json){using var doc=JsonDocument.Parse(json);return doc.RootElement.TryGetProperty("revision",out var value)&&value.TryGetInt32(out var number)&&number>=0?number:0;}
 public static bool IsCurrentRevision(int candidate,int current)=>candidate>=current;
 private static void Initialize(){if(community!=null)return;community=[];personal=[];
  try{using var stream=typeof(CommunityCorrections).Assembly.GetManifestResourceStream("reviewed-dialogue.json");if(stream!=null){var json=new StreamReader(stream).ReadToEnd();community=Parse(json);revision=RevisionOf(json);}}catch{}
  try{var cache=Path.Combine(Root,"community-reviewed.json");if(File.Exists(cache)&&new FileInfo(cache).Length<=1_000_000){var json=File.ReadAllText(cache);var parsed=Parse(json);if(IsCurrentRevision(RevisionOf(json),revision)){community=parsed;revision=RevisionOf(json);}}}catch{}
  try{var path=Path.Combine(Root,"personal-reviewed.json");if(File.Exists(path)&&new FileInfo(path).Length<=2_000_000)personal=NormalizePersonal(JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(path))??[]);}catch{}}
 public static Dictionary<string,string> NormalizePersonal(Dictionary<string,string> saved){var result=new Dictionary<string,string>();foreach(var pair in saved){var split=pair.Key.IndexOf('\n');if(split>0)result[Key(pair.Key[..split],pair.Key[(split+1)..])]=pair.Value;}return result;}
 public static string? Find(string game,string source){lock(Sync){Initialize();var key=Key(game,source);return personal!.GetValueOrDefault(key)??community!.GetValueOrDefault(key);}}
 public static void SavePersonal(string game,string source,string arabic){if(string.IsNullOrWhiteSpace(game)||game.Length>200||string.IsNullOrWhiteSpace(source)||source.Length>2000||string.IsNullOrWhiteSpace(arabic)||arabic.Length>3000)throw new ArgumentException("Invalid correction.");lock(Sync){Initialize();personal![Key(game,source)]=arabic.Trim();Directory.CreateDirectory(Root);var path=Path.Combine(Root,"personal-reviewed.json");File.WriteAllText(path+".tmp",JsonSerializer.Serialize(personal));File.Move(path+".tmp",path,true);}}
 public static async Task<string> RefreshAsync(bool force=false){lock(Sync){Initialize();if(refreshing)return "تحديث التصحيحات جارٍ.";if(!force&&!Automatic)return "التحديث التلقائي متوقف.";var file=Path.Combine(Root,"community-reviewed.json");if(!force&&File.Exists(file)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(file)<TimeSpan.FromHours(12))return "التصحيحات محدثة.";refreshing=true;}
  try{using var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(20)};http.DefaultRequestHeaders.UserAgent.ParseAdd("ArabicGames-Reviewed/1");using var response=await http.GetAsync(Url,HttpCompletionOption.ResponseHeadersRead).ConfigureAwait(false);if(response.StatusCode!=HttpStatusCode.OK)return "تعذر تحديث التصحيحات: HTTP "+(int)response.StatusCode;await using var input=await response.Content.ReadAsStreamAsync().ConfigureAwait(false);using var memory=new MemoryStream();var buffer=new byte[8192];int n;while((n=await input.ReadAsync(buffer).ConfigureAwait(false))>0){if(memory.Length+n>1_000_000)throw new InvalidDataException();memory.Write(buffer,0,n);}var json=System.Text.Encoding.UTF8.GetString(memory.ToArray());var updated=Parse(json);lock(Sync){if(!IsCurrentRevision(RevisionOf(json),revision))return "التصحيحات الموجودة أحدث من الخادم.";}Directory.CreateDirectory(Root);var path=Path.Combine(Root,"community-reviewed.json");await File.WriteAllTextAsync(path+".tmp",json).ConfigureAwait(false);File.Move(path+".tmp",path,true);lock(Sync){community=updated;revision=RevisionOf(json);}return "تم تحديث التصحيحات المراجعة: "+updated.Count+" سطرًا. ستُستخدم قبل المحرك.";}catch{return "تعذر التنزيل؛ التصحيحات الموجودة محفوظة وتعمل.";}finally{lock(Sync)refreshing=false;}
 }
}
